// Ajoute l'Algerie a la liste des nationalites "faciles" de la Grille.
// L'Algerie n'avait que 3 joueurs en base (Mahrez, Bentaleb, Delort), pas
// assez repartis sur les clubs prioritaires pour generer un seul combo
// valide - 5 internationaux algeriens connus ajoutes (Slimani, Bennacer,
// Bensebaini, Feghouli, Ghezzal) pour donner a l'Algerie une vraie
// presence a Monaco/Lyon/AC Milan/Dortmund/Valencia. VALID_GRIDS
// regenere (400 combos, 13 nationalites desormais) et verifie a 0 case
// injouable contre le nouveau roster de 658 joueurs.
// Run from strikr-app/: node patch-grid-add-algeria.js
const fs = require('fs');
const path = require('path');

function write(rel, content) {
  const full = path.join(process.cwd(), rel);
  fs.writeFileSync(full, content);
  console.log('WROTE', rel);
}

